import { setTimeout as delay, setImmediate as immediate, setInterval as interval, scheduler } from 'node:timers/promises';
import timers from 'node:timers';

export async function report() {
  const line = (name, value) => console.log(name, JSON.stringify(value));
  const shape = e => [e.name, e.code, e.message];
  const reject = async (name, fn) => { try { await fn(); line(name, 'no error'); } catch (e) { line(name, shape(e)); } };
  for (const value of [null, false, '5', {}, [], 1n, Symbol('delay')]) {
    await reject('timeout delay', () => delay(value));
    const iterator = interval(value);
    line('interval lazy validation', typeof iterator.next);
    await reject('interval delay', () => iterator.next());
    await reject('scheduler delay', () => scheduler.wait(value));
  }
  for (const value of [null, false, 3, 'bad', [], () => {}]) {
    await reject('timeout options', () => delay(1, undefined, value));
    await reject('immediate options', () => immediate(undefined, value));
    await reject('interval options', () => interval(1, undefined, value).next());
  }
  for (const key of ['signal', 'ref']) {
    for (const value of [null, 0, 'bad', {}]) {
      const options = { [key]: value };
      await reject('timeout ' + key, () => delay(1, undefined, options));
      await reject('immediate ' + key, () => immediate(undefined, options));
      await reject('interval ' + key, () => interval(1, undefined, options).next());
    }
  }
  {
    let threw = false, promise;
    try { promise = delay('bad'); } catch { threw = true; }
    line('invalid returns rejection', [threw, promise instanceof Promise]);
    await promise.catch(() => {});
    line('default values', [await delay(), await immediate(), await scheduler.wait(0), await scheduler.yield()]);
    const value = { answer: 42 };
    line('timeout value identity', await delay(1.5, value) === value);
    line('immediate value identity', await immediate(value) === value);
  }
  for (const kind of ['timeout', 'immediate', 'scheduler']) {
    for (const preaborted of [false, true]) {
      const ac = new AbortController(), cause = { why: 'cancelled' };
      ac.signal.addEventListener('abort', e => e.stopImmediatePropagation());
      if (preaborted) ac.abort(cause);
      const promise = kind === 'timeout' ? delay(60000, 'unused', { signal: ac.signal })
        : kind === 'immediate' ? immediate('unused', { signal: ac.signal })
        : scheduler.wait(60000, { signal: ac.signal });
      if (!preaborted) ac.abort(cause);
      try { await promise; } catch (e) { line('cancelled ' + kind, [preaborted, ...shape(e), e.cause === cause]); }
    }
  }
  {
    const ac = new AbortController(); ac.abort();
    try { await delay(60000, undefined, { signal: ac.signal }); }
    catch (e) { line('default abort cause', [shape(e), e.cause === ac.signal.reason, e.cause.name]); }
  }
  {
    const ac = new AbortController(); let removed = 0;
    const original = ac.signal.removeEventListener.bind(ac.signal);
    ac.signal.removeEventListener = (...args) => { removed++; return original(...args); };
    await delay(1, undefined, { signal: ac.signal });
    await immediate(undefined, { signal: ac.signal });
    await scheduler.wait(1, { signal: ac.signal });
    const iterator = interval(1, undefined, { signal: ac.signal }); await iterator.next(); await iterator.return();
    line('completed signal cleanup', removed); ac.abort('after completion');
  }
  {
    const ac = new AbortController(); let removed = 0;
    const original = ac.signal.removeEventListener.bind(ac.signal);
    ac.signal.removeEventListener = (...args) => { removed++; return original(...args); };
    const promise = delay(60000, undefined, { signal: ac.signal }); ac.abort('early');
    await promise.catch(() => {}); line('cancelled signal cleanup', removed);
  }
  {
    const value = { tick: 'value' }, iterator = interval(1, value);
    line('interval self', iterator[Symbol.asyncIterator]() === iterator);
    line('interval identity', (await iterator.next()).value === value);
    line('interval return', await iterator.return('finished'));
    line('interval done', await iterator.next());
    let ticks = 0; for await (const value of interval(1, 'tick')) { if (value === 'tick') ticks++; if (ticks === 3) break; }
    line('interval loop break', ticks);
  }
  for (const preaborted of [false, true]) {
    const ac = new AbortController(), cause = { why: 'interval cancellation' };
    ac.signal.addEventListener('abort', e => e.stopImmediatePropagation());
    if (preaborted) ac.abort(cause);
    const iterator = interval(60000, 'unused', { signal: ac.signal });
    const a = iterator.next().catch(e => [shape(e), e.cause === cause]), b = iterator.next();
    if (!preaborted) ac.abort(cause);
    line('interval cancelled', [preaborted, await a, await b, await iterator.next()]);
  }
  {
    const ac = new AbortController(), iterator = interval(5, 'buffered', { signal: ac.signal });
    await iterator.next(); await delay(100); ac.abort('buffered abort');
    line('interval drains buffered tick', await iterator.next()); await iterator.return();
  }
  {
    const iterator = interval(1, 'value'), failure = new Error('thrown');
    await iterator.next(); try { await iterator.throw(failure); } catch (e) { line('interval throw identity', e === failure); }
    line('interval throw done', await iterator.next());
    const lazy = interval('invalid delay'); line('return before start', await lazy.return('skipped'));
  }
  {
    const keep = setTimeout(() => {}, 60000);
    line('unref timeout with live loop', await delay(1, 'value', { ref: false }));
    line('unref immediate with live loop', await immediate('value', { ref: false }));
    const iterator = interval(1, 'value', { ref: false }); line('unref interval with live loop', await iterator.next()); await iterator.return();
    await scheduler.wait(1, { ref: false }); line('unref scheduler with live loop', true); clearTimeout(keep);
  }
  {
    const log = [];
    await new Promise(resolve => setImmediate(() => {
      setImmediate(() => log.push('first'));
      queueMicrotask(() => log.push('microtask'));
      setImmediate(() => { log.push('second'); setImmediate(() => { log.push('nested'); resolve(); }); });
    }));
    line('immediate queue', log);
    line('global module identity', [timers.setImmediate === setImmediate, timers.clearImmediate === clearImmediate]);
  }
  {
    const timer = setTimeout(() => {}, 60000), id = +timer;
    line('timeout ref control', [timer.hasRef(), timer.unref() === timer, timer.hasRef(), timer.ref() === timer, timer.hasRef()]);
    timer.unref(); timer.refresh(); line('refresh preserves ref and identity', [timer.hasRef(), +timer === id]);
    clearTimeout(String(id)); timer.refresh(); line('cleared timeout stays cleared', timer.hasRef());
    const disposable = setTimeout(() => line('disposed timer ran', true), 60000);
    line('timeout disposal', disposable[Symbol.dispose]() === undefined);
    const stopped = setInterval(() => line('disposed interval ran', true), 60000); stopped[Symbol.dispose]();
    const fired = setTimeout(function(a, b) { line('timeout receiver', [this === fired, a, b]); }, 1, 'a', 'b');
    await delay(10); line('fired timeout ref', fired.hasRef());
    const refreshed = new Promise(resolve => {
      let calls = 0;
      const handle = setTimeout(() => { if (++calls === 1) handle.refresh(); else { line('refresh after firing', calls); resolve(); } }, 1);
    }); await refreshed;
  }
  {
    const handle = setImmediate(() => line('cleared immediate ran', true));
    line('immediate ref control', [handle.hasRef(), handle.unref() === handle, handle.hasRef(), handle.ref() === handle, handle.hasRef()]);
    clearImmediate(handle); line('cleared immediate ref', handle.hasRef());
    line('immediate disposal', setImmediate(() => line('disposed immediate ran', true))[Symbol.dispose]() === undefined);
    await new Promise(resolve => {
      const fired = setImmediate(function(a, b) { line('immediate receiver', [this === fired, a, b, fired.hasRef()]); resolve(); }, 'a', 'b');
    });
  }
  {
    line('scheduler prototype', Object.getOwnPropertyNames(Object.getPrototypeOf(scheduler)));
    await reject('scheduler constructor', () => new scheduler.constructor());
    await reject('scheduler wait receiver', () => scheduler.wait.call({}, 1));
    await reject('scheduler yield receiver', () => scheduler.yield.call({}));
    const ac = new AbortController(); let signals = 0, refs = 0;
    const options = { get signal() { signals++; return ac.signal; }, get ref() { refs++; return true; } };
    await delay(1, undefined, options); await immediate(undefined, options);
    const iterator = interval(1, undefined, options); await iterator.next(); await iterator.return();
    line('option getters', [signals, refs]);
  }
}

export function unref() {
  const unexpected = () => console.log('unreferenced timer fired');
  setTimeout(unexpected, 60000).unref();
  setInterval(unexpected, 60000).unref();
  setImmediate(unexpected).unref();
  delay(60000, undefined, { ref: false }).then(unexpected);
  immediate(undefined, { ref: false }).then(unexpected);
  interval(60000, undefined, { ref: false }).next().then(unexpected);
  scheduler.wait(60000, { ref: false }).then(unexpected);
  console.log('scheduled unreferenced timers');
}
